/// enum E {
///     A,
///     B,
///     #[doc(hidden)]
///     _C,
/// }
///
/// struct T(pub i32, pub i32, ());
/// ```
/// Use instead:
/// ```no_run
/// #[non_exhaustive]
/// struct S {
///     pub a: i32,
///     pub b: i32,
/// }
